import test from 'node:test';import assert from 'node:assert/strict';
import {parseProbateCSV,mergeCases,caseNumber,casePriority,verifiedLink,casesCSV,partiesCSV,researchDetailsCSV,newCase} from './assets/probate-logic.mjs';
import {storageSession,WORKSPACE_KEY,SNAPSHOT_KEY,validateWorkspace,backupWorkspace,mergeBackup} from './assets/workspace.mjs';import {normalize} from './assets/logic.mjs';
const header='CaseCategory,CaseTypeDescription,CaseNumber,Title,FilingDate,PartyType,FirstName,MiddleName,LastName/CompanyName,DateofDeath,PartyAddress,Attorney';
const row=(role='Decedent',number='26-CP-003549',attorney='No Attorney')=>`PR,Formal Administration,${number},FICTIONAL ESTATE,10/13/2026,${role},Fictional,,Person,,"Party address, not property",${attorney}`;
const source={id:'fixture-hash',file:'fixture.csv',importedAt:'2026-10-27T10:00:00Z'};const parse=(lines=[row()])=>parseProbateCSV(header+'\n'+lines.join('\n'),source);
const empty=()=>({version:4,records:[],cases:[],history:[],outreachSettings:{}});
function memory(seed={}){const m=new Map(Object.entries(seed));return {getItem:k=>m.has(k)?m.get(k):null,setItem:(k,v)=>m.set(k,v),m};}
const property=()=>normalize({parcelid:'123.0000',address:'Fictional property',owner:'Fictional Person'});
const date=()=>new Date().toISOString().slice(0,10);
test('Raw party rows import without a property address and group by case',()=>{const p=parse([row(),row('Petitioner')]);assert.equal(p.cases.length,1);assert.equal(p.cases[0].parties.length,2);assert.equal(p.cases[0].links.length,0);assert.equal(p.cases[0].status,'Unmatched');assert.equal(p.cases[0].parties[0].address,'Party address, not property');});
test('Court case numbers normalize year, whitespace, and leading zero formats',()=>{assert.equal(caseNumber('2026 cp 3549'),'26-CP-003549');assert.equal(caseNumber('26-CP-003549'),'26-CP-003549');assert.equal(caseNumber('bad'),'');});
test('Repeated daily imports are idempotent; new attorney data preserves old row and research',()=>{let c=mergeCases([],parse().cases).cases;c[0].notes='Keep research';c[0].followup='2026-11-01';const repeat=mergeCases(c,parse().cases);assert.equal(repeat.unchanged,1);assert.deepEqual(repeat.cases,c);const changed=mergeCases(c,parse([row('Decedent',undefined,'Fixture Attorney')]).cases);assert.equal(changed.updated,1);assert.equal(changed.cases[0].parties.length,2);assert.equal(changed.cases[0].notes,'Keep research');assert.equal(changed.cases[0].followup,'2026-11-01');});
test('New daily sources retained without duplicate party snapshots',()=>{const first=parse().cases,second=parseProbateCSV(header+'\n'+row(),{...source,id:'second-day',file:'next.csv'}).cases;const c=mergeCases(first,second).cases[0];assert.equal(c.sources.length,2);assert.equal(c.parties.length,1);assert.equal(c.parties[0].sources.length,2);});
test('Guardianship classified separately and earns no estate priority',()=>{const p=parseProbateCSV((header+'\n'+row()).replace('Formal Administration','Guardian Advocate Pers/Prop'),source);assert.equal(p.cases[0].classification,'Non-estate / review');assert.equal(casePriority(p.cases[0],[]).score,0);});
test('Invalid rows reported with line number while valid cases remain in preview',()=>{const p=parse([row(),row('Decedent','bad')]);assert.equal(p.issues[0].row,3);assert.equal(p.validRows,1);assert.equal(p.cases.length,1);});
test('Malformed CSV fails; missing court schema rejected',()=>{assert.throws(()=>parseProbateCSV(header+'\n"broken',source));assert.throws(()=>parseProbateCSV('address,owner\nFixture,Owner',source),/Expected Clerk headers/);});
test('Evidence score requires current verified parcel and documents; no filing-only points',()=>{const c=parse().cases[0],r=property();assert.equal(casePriority(c,[r]).score,0);const l={propertyId:r.id,identityMatched:true,ownershipMatched:true,authorityMatched:true,date:date(),url:'https://example.com/record',note:'Fixture verified evidence'};c.links.push(l);assert.equal(verifiedLink(l,[r]),true);assert.equal(casePriority(c,[r]).score,50);c.evidence.push({propertyId:r.id,kind:'Vacancy',date:date(),url:'https://example.com/case',note:'Fixture documented vacancy'});assert.equal(casePriority(c,[r]).score,60);assert.equal(casePriority(c,[]).score,0);c.links[0].date='2020-01-01';assert.equal(casePriority(c,[r]).score,0);});
test('Case CSV and party CSV escape formulas and retain typed records',()=>{const c=parse().cases[0];c.notes='=SUM(1,2)';assert.match(casesCSV([c],[]),/'=SUM/);assert.match(partiesCSV([c]),/party_address_not_verified_property/);c.activity.push({at:'2026-10-27',action:'Review',note:'Keep history'});assert.match(researchDetailsCSV([c]),/Keep history/);});
test('Migration preserves exact original keys, creates recovery snapshot and v4 records',()=>{const r=property();r.notes='Legacy note';r.outreach={drafts:{letter:'Keep my draft'},events:[{at:'2026-01-01',channel:'letter',outcome:'Printed',note:'Original'}]};r.customField='Keep unknown fields';const raw=JSON.stringify([r]),m=memory({'baruch-ermi-leads-v1':raw});const session=storageSession(m);assert.equal(m.getItem(WORKSPACE_KEY),null);const next=session.save(session.initial);assert.equal(m.getItem('baruch-ermi-leads-v1'),raw);assert.ok(m.getItem(SNAPSHOT_KEY));assert.deepEqual(next.records[0],r);assert.deepEqual(storageSession(m).initial.records,[r]);});
test('Repeated save increments revisions without duplicating cases',()=>{const m=memory(),s=storageSession(m),v=s.initial;v.cases=parse().cases;assert.equal(s.save(v).revision,1);assert.equal(s.save(v).revision,2);assert.equal(storageSession(m).initial.cases.length,1);});
test('Malformed old data locks migration without overwrite',()=>{const raw='bad json',m=memory({'baruch-ermi-leads-v1':raw});assert.throws(()=>storageSession(m));assert.equal(m.getItem('baruch-ermi-leads-v1'),raw);assert.equal(m.getItem(WSPACE_KEY),null);});
const WSPACE_KEY=WORKSPACE_KEY;
test('Storage quota errors never erase original records or claim a saved v4',()=>{const raw=JSON.stringify([property()]),m=memory({'baruch-ermi-leads-v1':raw}),s=storageSession(m);m.setItem=()=>{throw Error('QuotaExceededError');};assert.throws(()=>s.save(s.initial),/Quota/);assert.equal(m.getItem('baruch-ermi-leads-v1'),raw);assert.equal(m.getItem(WORKSPACE_KEY),null);});
test('Two-tab stale writes are refused',()=>{const m=memory(),a=storageSession(m),b=storageSession(m);a.save(a.initial);const before=m.getItem(WORKSPACE_KEY);assert.throws(()=>b.save(b.initial),/Another tab/);assert.equal(m.getItem(WORKSPACE_KEY),before);});
test('Legacy tab changes are detected before migration',()=>{const m=memory(),s=storageSession(m);m.setItem('baruch-ermi-leads-v1',JSON.stringify([property()]));assert.throws(()=>s.save(s.initial),/Legacy records changed/);});
test('Backup v1–v4 supported; merging keeps current edits and stores conflict copies',()=>{for(const version of [1,2,3,4])assert.equal(backupWorkspace({version,records:[]}).version,4);const r=property(),current={...empty(),records:[r]},incoming=structuredClone(current);incoming.records[0].notes='Different backup note';incoming.cases=parse().cases;const result=mergeBackup(current,incoming);assert.equal(result.workspace.records[0].notes,'');assert.equal(result.workspace.recoveryCopies[0].record.notes,'Different backup note');assert.equal(result.workspace.cases.length,1);assert.equal(result.conflicts,1);});
test('Full JSON backup roundtrip retains linked verification, evidence, history and property extras',()=>{const r=property(),c=parse().cases[0];c.links.push({propertyId:r.id,date:date(),url:'https://example.com/record',note:'Fixture',identityMatched:true,ownershipMatched:true});const v={...empty(),records:[r],cases:[c],history:[{kind:'Fixture'}],outreachSettings:{name:'Ermias'}};assert.deepEqual(backupWorkspace(JSON.parse(JSON.stringify(v))),v);});
test('Bad backups and dangling parcel references rejected without partial restore',()=>{assert.throws(()=>backupWorkspace({version:8,records:[]}));const c=parse().cases[0];c.links=[{propertyId:'missing',date:date(),url:'https://example.com',note:'Fixture'}];assert.throws(()=>validateWorkspace({...empty(),cases:[c]}),/missing property/);});
test('Clerk PN, WD and MH case numbers are retained without scoring as estate leads',()=>{for(const [code,type,classification] of [['PN','Pre - Need Guardianship','Non-estate / review'],['WD','Wills on Deposit','Other / review'],['MH','Risk Protection','Non-estate / review']]){const p=parseProbateCSV((header+'\n'+row()).replace('26-CP-003549','26-'+code+'-003549').replace('Formal Administration',type),source);assert.equal(p.issues.length,0);assert.equal(p.cases[0].classification,classification);assert.equal(casePriority(p.cases[0],[]).score,0);}});
test('Restoring an opted-out property never re-enables its contact channels',()=>{const r=property(),current={...empty(),records:[r]},incoming=structuredClone(current);incoming.records[0].stage='Do not contact';incoming.records[0].outreach={suppressed:true};const merged=mergeBackup(current,incoming).workspace;assert.equal(merged.records[0].stage,'Do not contact');assert.equal(merged.records[0].outreach.suppressed,true);});
test('Built worker serves every new ES module needed by the case manager',async()=>{const worker=(await import('./worker/index.js')).default;for(const name of ['probate.mjs','probate-logic.mjs','workspace.mjs']){const response=await worker.fetch(new Request('https://fixture.test/'+name));assert.equal(response.status,200);assert.match(response.headers.get('content-type'),/javascript/);}});
